#
# Structure for table "notifications"
#

DROP TABLE IF EXISTS `notifications`;
CREATE TABLE `notifications` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) NOT NULL,
  `type` enum('PRICE_ALERT','NEWS','SYSTEM') DEFAULT NULL,
  `title` varchar(255) DEFAULT NULL,
  `content` text,
  `stock_code` varchar(20) DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_user_read` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8;

#
# Data for table "notifications"
#

INSERT INTO `notifications` VALUES (4,3,'PRICE_ALERT','异动雷达：云赛智联 涨幅突破 4%！','自选股【云赛智联(600602)】今日多头强劲，实时涨幅已达 4.01%。','600602','2026-06-30 14:09:34'),(5,3,'PRICE_ALERT','风险预警：宝新能源 跌破 -1.0%！','自选股【宝新能源(000690)】今日遭遇砸盘，实时跌幅已达 -1.05%，已触及您设置的 -1.0% 下跌风险线。','000690','2026-06-30 14:59:19');

#
# Structure for table "price_alerts"
#

DROP TABLE IF EXISTS `price_alerts`;
CREATE TABLE `price_alerts` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) DEFAULT NULL,
  `symbol` varchar(20) DEFAULT NULL,
  `market` varchar(10) DEFAULT NULL,
  `condition_type` enum('GT','LT') DEFAULT NULL,
  `target_price` decimal(12,4) DEFAULT NULL,
  `enabled` tinyint(1) DEFAULT '1',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

