#
# Structure for table "stock_basic"
#

DROP TABLE IF EXISTS `stock_basic`;
CREATE TABLE `stock_basic` (
  `stock_code` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '股票代码',
  `stock_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '股票名称',
  `company_full_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '公司全称',
  `former_names` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '曾用名，多个以逗号分隔',
  `market_type` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '市场类型（如 SH/SZ/BJ）',
  `board` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '板块（主板/科创板/创业板/北交所）',
  `industry` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '所属行业',
  `latest_close` decimal(10,3) DEFAULT NULL COMMENT '最新收盘价',
  `trade_date` date DEFAULT NULL COMMENT '收盘价对应的交易日期',
  `list_date` date DEFAULT NULL COMMENT '上市日期',
  `status` tinyint(4) DEFAULT '1' COMMENT '状态：1正常 0停牌 2退市',
  `type` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'stock' COMMENT '品种类型：stock/etf/fund/index/bond/other',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`stock_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='股票基础信息表';

