#
# Structure for table "system_configs"
#

DROP TABLE IF EXISTS `system_configs`;
CREATE TABLE `system_configs` (
  `config_key` varchar(100) NOT NULL,
  `config_value` text,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`config_key`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

#
# Data for table "system_configs"
#

/*!40000 ALTER TABLE `system_configs` DISABLE KEYS */;
/*!40000 ALTER TABLE `system_configs` ENABLE KEYS */;

#
# Structure for table "user_settings"
#

DROP TABLE IF EXISTS `user_settings`;
CREATE TABLE `user_settings` (
  `user_id` bigint(20) NOT NULL COMMENT '用户ID，与users表关联',
  `enable_alerts` tinyint(1) DEFAULT '1' COMMENT '是否开启全局预警开关（1开启 0关闭）',
  `up_threshold` float DEFAULT '6.5' COMMENT '上涨提醒阈值（百分比）',
  `down_threshold` float DEFAULT '5' COMMENT '下跌提醒阈值（百分比）',
  `channel_pocket` tinyint(1) DEFAULT '1' COMMENT '是否启用“口袋”渠道提醒',
  `channel_agent` tinyint(1) DEFAULT '0' COMMENT '是否启用“智能体”渠道提醒',
  PRIMARY KEY (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='用户个人设置表';

