#
# Structure for table "watchlist_items"
#

DROP TABLE IF EXISTS `watchlist_items`;
CREATE TABLE `watchlist_items` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `group_id` bigint(20) DEFAULT NULL COMMENT '所属分组ID',
  `stock_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '股票代码，对应 stock_basic 的 stock_code',
  `sort_order` int(11) DEFAULT '0' COMMENT '自选股在当前分组内的排序序号，数字越小越靠前',
  `note` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户针对该股票的个人备注',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '添加时间',
  `change_pct` decimal(10,6) DEFAULT '0.000000',
  `last_price` decimal(10,2) DEFAULT '0.00',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_group_stock` (`user_id`,`group_id`,`stock_code`),
  KEY `group_id` (`group_id`),
  KEY `stock_code` (`stock_code`),
  KEY `idx_user_stock` (`user_id`,`stock_code`),
  CONSTRAINT `watchlist_items_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `watchlist_items_ibfk_2` FOREIGN KEY (`group_id`) REFERENCES `watchlist_groups` (`id`) ON DELETE CASCADE,
  CONSTRAINT `watchlist_items_ibfk_3` FOREIGN KEY (`stock_code`) REFERENCES `stock_basic` (`stock_code`)
) ENGINE=InnoDB AUTO_INCREMENT=27 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户自选股明细表';

